import "package:flutter_test/flutter_test.dart"; import "package:youtube_explode_dart/youtube_explode_dart.dart"; void main() { test("Test related videos", () async { final yt = YoutubeExplode(); try { final song = await yt.videos.get("dQw4w9WgXcQ"); final related = await yt.videos.getRelatedVideos(song); print("Success! Count: ${related?.length}"); } catch(e) { print("Error! $e"); } finally { yt.close(); } }); }
